package dev.algorithmlearning.api.reviews.application; import dev.algorithmlearning.api.problems.application.ProblemRepository; import dev.algorithmlearning.api.reviews.domain.FixedReviewPolicy; import java.time.*; import java.util.*; import org.springframework.transaction.annotation.Transactional; public class ReviewService {private final ProblemRepository problems;private final ReviewRepository reviews;private final Clock clock;private final FixedReviewPolicy policy;public ReviewService(ProblemRepository p,ReviewRepository r,Clock c){problems=p;reviews=r;clock=c;policy=new FixedReviewPolicy();}@Transactional public Optional<Review> create(UUID owner,UUID problemId,int confidence,String notes){if(problems.findByIdAndUserId(problemId,owner).isEmpty())return Optional.empty();var now=clock.instant();return Optional.of(reviews.save(new Review(UUID.randomUUID(),problemId,confidence,now,policy.nextReviewAt(now,confidence),blank(notes),"fixed-v1")));}public List<Review> due(UUID owner,int page,int size){return reviews.due(owner,clock.instant(),size,(page-1)*size);}public List<Review> history(UUID owner,UUID problemId,int page,int size){return reviews.history(owner,problemId,size,(page-1)*size);}private static String blank(String v){return v==null||v.trim().isEmpty()?null:v.trim();}}
